-- 027: rebuild Jubail/Yanbu program lists from the booklet (pp.133-134) + RCJY official site/catalog.
-- Updates 16 existing rows, inserts 39. Backup: backup.guide_programs_027.
-- Rollback: delete rows of these two universities not in backup, then restore name/college/degree/gender/campus/admission_route/source_url from backup.
create table backup.guide_programs_027 as select * from public.guide_programs where university_id in ('c0c3a057-c9ab-45e3-8f18-f444045f2289','cdff6e19-74ed-4858-a4bf-c9953c84f40d');
do $c$ declare n int; begin
  perform set_config('request.jwt.claim.sub',(select user_id::text from public.guide_admins where is_owner and is_enabled limit 1),true);
  update public.guide_programs g set name=v.name, college=v.college, degree=v.degree, gender=v.gender, campus='', admission_route='', source_url='' from (values
   ('c70ceb78-5b52-4c80-aa01-e8b7e1b3193b'::uuid,'الهندسة الكهربائية','كلية الجبيل الصناعية','بكالوريوس','طلاب'),
