   ('2e600253-b17f-4028-841e-123c5ce46f2e'::uuid,'الهندسة الكيميائية','كلية الجبيل الصناعية','بكالوريوس','طلاب'),
   ('1187d51b-6a79-48dd-980b-0dd0b0de415b'::uuid,'الهندسة الميكانيكية','كلية الجبيل الصناعية','بكالوريوس','طلاب'),
   ('72e3610d-2d41-4d10-8f26-0d38b8dcf278'::uuid,'الهندسة المدنية','كلية الجبيل الصناعية','بكالوريوس','طلاب'),
