   ('af900637-c3ea-4f6d-90e4-885356992ca4'::uuid,'إدارة الأعمال','كلية الجبيل الصناعية','بكالوريوس','الجميع'),
   ('7e2dbad6-b715-42bb-be39-ee4e6a4b0f8e'::uuid,'علوم الحاسب الآلي','كلية الجبيل الصناعية','بكالوريوس','الجميع'),
   ('0aee78b0-979c-44a8-9903-565674c3f290'::uuid,'هندسة الحاسب الآلي','كلية ينبع الصناعية','بكالوريوس','الجميع'),
   ('8aa4eef3-251f-4592-be5a-2dcafddffb4a'::uuid,'إدارة الأعمال — الموارد البشرية','كلية ينبع الصناعية','بكالوريوس','الجميع'),
   ('4ad5c7fa-cc55-45ea-8563-cc984b85ef71'::uuid,'نظم المعلومات الإدارية','كلية ينبع الصناعية','بكالوريوس','الجميع'),
   ('583837d4-864f-43a6-9b3e-fc6e5a12c142'::uuid,'إدارة سلسلة الإمداد','كلية ينبع الصناعية','بكالوريوس','طلاب'),
   ('280699de-abdf-4a39-a13e-f1dc345f00b0'::uuid,'التسويق','كلية ينبع الصناعية','بكالوريوس','طلاب'),
   ('33011bbe-728b-4232-adb0-bd39a7187943'::uuid,'تقنية تشغيل العمليات والتحاليل الكيميائية','كلية ينبع الصناعية','دبلوم','الجميع'),
   ('9c91dd2e-8c5a-43a1-b1e7-cd2b7cd1f46e'::uuid,'تقنية الصيانة الميكانيكية','كلية ينبع الصناعية','دبلوم','طلاب'),
