  get diagnostics n=row_count; if n<>16 then raise exception 'update count %', n; end if;
  get diagnostics n=row_count; if n<>39 then raise exception 'insert count %', n; end if;
  select count(*) into n from public.guide_programs where university_id in ('c0c3a057-c9ab-45e3-8f18-f444045f2289','cdff6e19-74ed-4858-a4bf-c9953c84f40d') and deleted_at is null; if n<>55 then raise exception 'final count %', n; end if;
end $c$;
